import {
  bigint,
  boolean,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uuid,
  check,
} from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'
import { id, timestamps } from './columns'

/**
 * Better Auth's tables, in the shape its Drizzle adapter expects for 1.7.x:
 * the property keys are Better Auth's logical field names (`emailVerified`,
 * `userId`, …), the column names are snake_case. Ids are UUIDv7, generated by
 * the app (`advanced.database.generateId` in the auth config, issue #158).
 *
 * The user row stays generic (spec §1: it will become the SVEF member
 * account): name, phone and preferred locale are the only additions, declared
 * to Better Auth through `user.additionalFields`. Nothing awards-specific.
 *
 * Better Auth hard-deletes sessions and verifications itself; `deleted_at`
 * is present for the convention and used only for `user` (soft-delete).
 */
export const user = pgTable(
  'user',
  {
    id: id(),
    name: text('name').notNull(),
    email: text('email').notNull().unique(),
    emailVerified: boolean('email_verified').notNull().default(false),
    image: text('image'),
    phone: text('phone'),
    preferredLocale: text('preferred_locale'),
    ...timestamps,
  },
  (t) => [
    check('user_preferred_locale_check', sql`${t.preferredLocale} in ('is', 'en')`),
  ],
)

export const session = pgTable(
  'session',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    token: text('token').notNull().unique(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    ...timestamps,
  },
  (t) => [index('session_user_id_idx').on(t.userId)],
)

export const account = pgTable(
  'account',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: timestamp('access_token_expires_at', { withTimezone: true }),
    refreshTokenExpiresAt: timestamp('refresh_token_expires_at', { withTimezone: true }),
    scope: text('scope'),
    password: text('password'),
    ...timestamps,
  },
  (t) => [index('account_user_id_idx').on(t.userId)],
)

export const verification = pgTable(
  'verification',
  {
    id: id(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    ...timestamps,
  },
  (t) => [index('verification_identifier_idx').on(t.identifier)],
)

/**
 * Better Auth's rate-limit counters (`rateLimit.storage: 'database'`): on
 * serverless the default in-memory store is per instance and so barely limits
 * anything. `key` is hashed IP + path; `lastRequest` is epoch milliseconds.
 * Not a record of anything, so no `deleted_at`; rows are overwritten in place.
 */
export const rateLimit = pgTable('rate_limit', {
  id: id(),
  key: text('key').notNull().unique(),
  count: integer('count').notNull(),
  lastRequest: bigint('last_request', { mode: 'number' }).notNull(),
})
